public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s == t) {
        return "can be travelled";
    }
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) continue;
        int u = p[0];
        int v = p[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        adj[u].add(v);
        adj[v].add(u);
    }
    boolean[] visited = new boolean[n];
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(s);
    visited[s] = true;
    while (!stack.isEmpty()) {
        int cur = stack.pop();
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                if (nb == t) {
                    return "can be travelled";
                }
                visited[nb] = true;
                stack.push(nb);
            }
        }
    }
    return "cannot be travelled";
}

