public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256];
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder result = new StringBuilder(s.length());
    int total = s.length();
    while (result.length() < total) {
        // Ascend from smallest to largest
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
        // Descend from largest to smallest
        for (int i = 255; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) i);
                freq[i]--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    // dp[k] will contain all possible sums of subsets of size k
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = n; k >= 1; k--) {
            java.util.Set<Integer> prev = dp.get(k - 1);
            if (!prev.isEmpty()) {
                java.util.Set<Integer> curr = dp.get(k);
                for (int sum : prev) {
                    curr.add(sum + num);
                }
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if (total % k == 0) {
            int target = total / k;
            if (dp.get(k).contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0; // Can start at step 1 (outside the array) for free.
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
