public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // current number of unmatched '('
    int insertions = 0;   // number of '(' inserted to fix imbalance
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                // need one '(' to pair with this ')'
                insertions++;
                balance = 0;
            }
        }
    }
    // any remaining '(' need corresponding ')'
    return insertions + balance;
}

