}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers <= k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) break;
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    // Greedy selection from largest to smallest
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        if (remaining >= fibs.get(i)) {
            remaining -= fibs.get(i);
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    int sqrt = (int) Math.sqrt(n);
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    int idxFromLarge = k - small.size(); // 1‑based index in the ascending part of large
    int revIndex = large.size() - idxFromLarge; // convert to 0‑based index in original large list
    return large.get(revIndex);
}

