public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update 'ones' to have bits that have appeared once (mod 3)
        ones = (ones ^ num) & ~twos;
        // Update 'twos' to have bits that have appeared twice (mod 3)
        twos = (twos ^ num) & ~ones;
    }
    // When the loop ends, 'ones' contains the bits of the unique number
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // zero is a stepping number
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    for (int i = 1; i <= 9; i++) {
        Queue<Long> queue = new LinkedList<>();
        queue.offer((long) i);
        while (!queue.isEmpty()) {
            long curr = queue.poll();
            if (curr > high) {
                continue;
            }
            if (curr >= low) {
                result.add((int) curr);
            }
            if (curr <= high / 10) {
                int lastDigit = (int) (curr % 10);
                if (lastDigit > 0) {
                    long next = curr * 10 + (lastDigit - 1);
                    queue.offer(next);
                }
                if (lastDigit < 9) {
                    long next = curr * 10 + (lastDigit + 1);
                    queue.offer(next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long result = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (current == 0) {
            result += higher * factor;
        } else if (current == 1) {
            result += higher * factor + lower + 1;
        } else {
            result += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) result;
}

