    }
    int m = mat.length;
    int n = mat[0].length;
    // Handle case where rows might have different lengths
    for (int[] row : mat) {
        if (row == null || row.length != n) {
            throw new IllegalArgumentException("All rows must have the same number of columns");
        }
    }

    int[][] horizontal = new int[m][n];
    int[][] vertical   = new int[m][n];
    int[][] diagonal   = new int[m][n]; // top-left to bottom-right (\)
    int[][] antiDiag   = new int[m][n]; // top-right to bottom-left (/)

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j]   = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j]   = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j]   = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;

                int cellMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiag[i][j]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j]   = 0;
                diagonal[i][j]   = 0;
                antiDiag[i][j]   = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (value > 0) {
        sb.append((char) ('0' + (int) (value % 10)));
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int n = heights.length;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        if (curHeight < 0) {
            throw new IllegalArgumentException("heights array contains negative value at index " + i);
        }
        while (!stack.isEmpty() && curHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] res = new int[total];
    int k = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int row = endRow; row >= startRow; row--) {
                int col = sum - row;
                if (col >= 0 && col < n) {
                    res[k++] = mat[row][col];
                }
            }
        } else {
            for (int row = startRow; row <= endRow; row++) {
                int col = sum - row;
                if (col >= 0 && col < n) {
                    res[k++] = mat[row][col];
                }
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

